static readonly HashSet<string> AllowedHosts = new(StringComparer.OrdinalIgnoreCase)
{
    "app.example.com",
    "help.example.com"
};

app.MapGet("/redirect", (string to) =>
{
    if (string.IsNullOrWhiteSpace(to))
        return Results.Redirect("/dashboard");

    if (Uri.TryCreate(to, UriKind.Relative, out var relativeUri))
        return Results.Redirect(relativeUri.ToString());

    if (Uri.TryCreate(to, UriKind.Absolute, out var absoluteUri))
    {
        if (absoluteUri.Scheme != "https")
            return Results.BadRequest("Only HTTPS is allowed");

        if (!AllowedHosts.Contains(absoluteUri.Host))
            return Results.BadRequest("Redirect domain not allowed");

        return Results.Redirect(absoluteUri.ToString());
    }

    return Results.BadRequest("Invalid URL");
});

static readonly HashSet<string> AllowedRedirectUris = new(StringComparer.Ordinal)
{
    "https://app.example.com/auth/callback",
    "https://admin.example.com/auth/callback"
};

app.MapGet("/authorize", (string redirect_uri) =>
{
    if (!AllowedRedirectUris.Contains(redirect_uri))
        return Results.BadRequest("Invalid redirect_uri");

    // Proceed with authorization
    var code = GenerateAuthorizationCode();
    return Results.Redirect($"{redirect_uri}?code={code}");
});
